fn all_sequence_equal_length(seq: &Vec<Vec<i32>>) -> bool {
    // If the outer list is empty, we consider all inner lengths to be trivially equal.
    if seq.is_empty() {
        return true;
    }

    // Take the length of the first inner array as the reference.
    let first_len = seq[0].len();

    // Check that every other inner array has the same length.
    for arr in seq.iter().skip(1) {
        if arr.len() != first_len {
            return false;
        }
    }

    true
}

